using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using Newtonsoft.Json;using Newtonsoft.Json.Linq;using Game.Configs;using Game.Skirmish.Contracts;using Game.Runtime;
internal static class SourceSmokeTool {
 static readonly Dictionary<string,string> pins=new Dictionary<string,string>(StringComparer.Ordinal);
 static readonly Dictionary<string,long> maxima=new Dictionary<string,long>(StringComparer.Ordinal);
 static JObject Parse(byte[] bytes){using var text=new StringReader(Encoding.UTF8.GetString(bytes));using var reader=new JsonTextReader(text){DateParseHandling=DateParseHandling.None};var value=JObject.Load(reader,new JsonLoadSettings{DuplicatePropertyNameHandling=DuplicatePropertyNameHandling.Error});if(reader.Read())throw new InvalidDataException("One complete smoke JSON document required");return value;}
 static byte[] Read(string path,string hash,long maximum){var bytes=AutonomousWorld.PinnedFile(path,hash,maximum);if(pins.TryGetValue(path,out var old)&&old!=hash)throw new InvalidDataException("Conflicting smoke input epoch");pins[path]=hash;maxima[path]=Math.Max(maxima.TryGetValue(path,out long prior)?prior:0,maximum);return bytes;}
 static JObject Descriptor(JObject owner,string name,long maximum){var row=owner[name]as JObject??throw new InvalidDataException("Descriptor required: "+name);if(row.Properties().Count()!=2||row["path"]?.Type!=JTokenType.String||row["sha256"]?.Type!=JTokenType.String)throw new InvalidDataException("Exact path/sha descriptor required: "+name);return Parse(Read((string)row["path"],(string)row["sha256"],maximum));}
 static JObject Stage(string id,string status,string field,string reason,JToken evidence=null)=>new JObject{["id"]=id,["status"]=status,["field"]=field,["reason"]=reason,["evidence"]=evidence};
 static JArray Reasons(IEnumerable<SkirmishCompileReason> reasons)=>new JArray(reasons.Select(x=>new JObject{["code"]=x.Code.ToString(),["field"]=x.Field,["detail"]=x.Detail}));
 public static bool TryRun(string[] args,out int code){code=0;if(args.Length==0||args[0]!="--source-smoke-data")return false;try{if(args.Length!=3)throw new ArgumentException("Explicit pinned smoke request required");Run(args[1],args[2]);}catch(Exception e){Console.Error.WriteLine(e);code=1;}return true;}
 static void Run(string path,string hash){
  var request=Parse(Read(path,hash,1024*1024));string[] keys={"schema_version","kind","mission","seed","initialization","runtime_config","output_directory"};if(request.Properties().Count()!=keys.Length||request.Properties().Any(x=>!keys.Contains(x.Name))||(int?)request["schema_version"]!=1||(string)request["kind"]!="SkirmishSourceSmokeData"||(string)request["mission"]!="S002"||(int?)request["seed"]!=104731)throw new NotSupportedException("Current native data-smoke scope is S002/104731; use author diagnostics for S026.");
  string directory=Path.GetFullPath((string)request["output_directory"]);if(!Directory.Exists(directory))throw new InvalidDataException("Prepared smoke directory required");var runtime=request["runtime_config"]as JObject??throw new InvalidDataException("Runtime descriptor required");Read((string)runtime["path"],(string)runtime["sha256"],1024*1024);var before=SourceRuntimeManifest.Write(directory,"before-smoke-data",(string)runtime["path"]);var stages=new JArray();
  SkirmishScenarioDefinitionConfig definition=null,catalogDefinition=null;SkirmishExpansionCatalogConfig catalog=null;System.Collections.Generic.IReadOnlyList<SkirmishSetupMatrixRow> matrix=null;JObject initialization=null;bool catalogReady=false;
  try{
   initialization=Descriptor(request,"initialization",4*1024*1024);if((int?)initialization["schema_version"]!=1||(string)initialization["kind"]!="GeneratedMissionInitialization"||(string)initialization["authority"]!="AuthoredConfigAndBakedCampaignMap"||(string)initialization["mission_id"]!="S002")throw new InvalidDataException("Actual authored S002 initialization required");
   var graph=Descriptor(initialization,"source_config_graph",16*1024*1024);foreach(var pin in((JObject)graph["source_pins"]).Properties())Read(pin.Name,(string)pin.Value,4*1024*1024);var values=new SourceConfigMaterializer(graph);definition=values.ByPath<SkirmishScenarioDefinitionConfig>((string)graph["definition_path"]);catalog=values.ByPath<SkirmishExpansionCatalogConfig>("Assets/Game/Resources/SkirmishExpansionCatalog.asset");if(definition.CatalogId!="S002"||!catalog.TryGetDefinition(definition.CatalogId,definition.ContentVersion,out catalogDefinition))throw new InvalidDataException("Actual unique authored definition/catalog identity missing");
   var selectedRow=((JArray)graph["nodes"]).OfType<JObject>().Single(x=>(string)x["source_path"]==(string)graph["definition_path"]);var catalogRows=((JArray)graph["nodes"]).OfType<JObject>().Where(x=>(string)x["source_type"]=="SkirmishScenarioDefinitionConfig"&&(string)x["fields"]?["catalogId"]==definition.CatalogId&&(int?)x["fields"]?["contentVersion"]==definition.ContentVersion&&ReferenceEquals(values.ByPath<SkirmishScenarioDefinitionConfig>((string)x["source_path"]),catalogDefinition)).ToArray();if(catalogRows.Length!=1)throw new InvalidDataException("Exact catalog-resolved source identity required");var catalogRow=catalogRows[0];
   if(!JToken.DeepEquals(selectedRow["fields"],catalogRow["fields"]))throw new InvalidDataException("Selected and catalog-resolved authored definition fields differ: "+(string)selectedRow["source_path"]+" versus "+(string)catalogRow["source_path"]);
   stages.Add(Stage("authored_definition_equivalence","Passed","definition.fields","Distinct assets retain exact serialized config values and shared source references; neither is aliased.",new JObject{["selected_path"]=selectedRow["source_path"],["selected_guid"]=selectedRow["asset_guid"],["catalog_path"]=catalogRow["source_path"],["catalog_guid"]=catalogRow["asset_guid"],["same_object"]=ReferenceEquals(definition,catalogDefinition),["all_serialized_config_fields_equal"]=true}));
   stages.Add(Stage("authored_definition_catalog","Passed","definition","Original authored catalog resolves the matching definition identity; actual graph-selected asset remains distinct.",new JObject{["catalog_id"]=definition.CatalogId,["definition_id"]=definition.DefinitionId,["content_version"]=definition.ContentVersion,["scope"]="Packaged authored definitions, not120playable missions"}));
   catalogReady=true;
  }catch(Exception e){stages.Add(Stage("authored_definition_catalog","Failed","initialization.source_config_graph",e.Message));}
  if(catalogReady){
   try{var desc=initialization["setup_matrix"]as JObject??throw new InvalidDataException("Matrix descriptor required");if(desc.Properties().Count()!=2||desc["path"]?.Type!=JTokenType.String||desc["sha256"]?.Type!=JTokenType.String)throw new InvalidDataException("Exact matrix path/sha descriptor required");var bytes=Read((string)desc["path"],(string)desc["sha256"],4*1024*1024);UnityEngine.Resources.BindSourceResources(new Dictionary<string,object>{[SkirmishExpansionCatalogConfig.ResourceName]=catalog,[SkirmishSetupMatrixTable.PackagedResourceName]=new UnityEngine.TextAsset(Encoding.UTF8.GetString(bytes))});if(!SkirmishSetupMatrixTable.TryLoadPackaged(out var loadedMatrix,out string error))throw new InvalidDataException(error);matrix=loadedMatrix;stages.Add(Stage("native_matrix","Passed","setup_matrix","Original matrix loader accepted pinned data.",new JObject{["rows"]=matrix.Count}));}catch(Exception e){stages.Add(Stage("native_matrix","Failed","setup_matrix",e.Message));}
  }else stages.Add(Stage("native_matrix","Skipped","setup_matrix","Depends on authored definition/catalog."));
  if(definition!=null&&matrix!=null){var selection=initialization["selection"]as JObject??throw new InvalidDataException("Actual setup selection required");var difficulty=(SkirmishDifficultyId)(int)selection["difficulty_id"];var size=(SkirmishSizeId)(int)selection["size_id"];int seed=(int)selection["seed"];if(seed!=104731)throw new InvalidDataException("Actual selected seed differs from smoke profile");var manifest=new SkirmishContentManifest{RequiredFeatureIds=definition.RequiredFeatureIds};var budgets=new JArray();bool budgetContractsAccepted=true;
   foreach(var candidate in new[]{SkirmishSizeId.Standard,SkirmishSizeId.War,SkirmishSizeId.LargeWar}){bool inspected=SkirmishSetupCompiler.TryInspectStaticAuthoringBudget(definition,difficulty,candidate,seed,manifest,matrix,out var budget,out var why);int actors=0;if(budget!=null)foreach(var force in budget.Forces)actors=checked(actors+force.Quantity);bool normal=SkirmishSetupCompiler.TryCompile(definition,difficulty,candidate,seed,manifest,matrix,out var acceptedSetup,out var normalReasons);bool reviewed=SkirmishLegacyLayoutBaselineContract.TryGetReviewedLayoutFingerprint(definition.CatalogId,out string reviewedLayout);bool protectedLegacy=normal&&reviewed&&SkirmishMeasuredLayoutBinder.PreservesPackagedLegacyBinding(acceptedSetup,definition,reviewedLayout);bool contractAccepted=inspected&&budget!=null&&normal&&budget.NormalCompilerPassed==normal&&(budget.ExactCanonicalQuantities||protectedLegacy);budgetContractsAccepted&=contractAccepted;budgets.Add(new JObject{["active_budget_contract"]=protectedLegacy?"OriginalProtectedPackagedLegacy":"Canonical",["original_preserves_packaged_legacy_binding"]=protectedLegacy,["active_contract_accepted"]=contractAccepted,["normal_compiler_reasons"]=Reasons(normalReasons),["size"]=candidate.ToString(),["inspected"]=inspected,["exact_canonical_quantities"]=budget?.ExactCanonicalQuantities,["actors"]=actors,["structures"]=budget?.Structures.Length,["normal_compiler_passed"]=budget?.NormalCompilerPassed,["canonical_budget_errors"]=budget==null?null:new JArray(budget.CanonicalBudgetErrors),["reasons"]=Reasons(why)});}
   stages.Add(Stage("native_static_budgets",budgetContractsAccepted?"Passed":"Failed","fixed_budgets",budgetContractsAccepted?"Original compiler budget contracts accepted; canonical diagnostics retained separately.":"Original selected budget contract rejected data.",budgets));bool compiled=SkirmishSetupCompiler.TryCompile(definition,difficulty,size,seed,manifest,matrix,out var setup,out var reasons);bool catalogCompiled=SkirmishSetupCompiler.TryCompile(catalogDefinition,difficulty,size,seed,manifest,matrix,out var catalogSetup,out var catalogReasons);bool equivalent=compiled&&catalogCompiled&&setup.SetupHash==catalogSetup.SetupHash;stages.Add(Stage("native_selected_compiler",equivalent?"Passed":"Failed","setup",equivalent?"Original compiler accepts both distinct source assets with equal compiled setup hashes.":"Original compiler rejection or selected/catalog compiled setup mismatch.",new JObject{["reasons"]=Reasons(reasons),["catalog_reasons"]=Reasons(catalogReasons),["selected_compiled"]=compiled,["catalog_compiled"]=catalogCompiled,["compiled_setup_hash_equal"]=equivalent,["catalog_id"]=definition.CatalogId,["seed"]=seed,["size"]=size.ToString(),["difficulty"]=difficulty.ToString()}));
  }else{stages.Add(Stage("native_static_budgets","Skipped","fixed_budgets","Depends on native matrix."));stages.Add(Stage("native_selected_compiler","Skipped","setup","Depends on native matrix."));}
  foreach(var pin in pins)AutonomousWorld.PinnedFile(pin.Key,pin.Value,maxima[pin.Key]);var result=new JObject{["schema_version"]=1,["kind"]="SkirmishNativeDataSmokeResult",["stages"]=stages,["input_pins"]=new JObject(pins.Select(x=>new JProperty(x.Key,x.Value))),["world_allocated"]=false,["source_fit_verified"]=false,["validation_passed"]=false};File.WriteAllText(Path.Combine(directory,"native-data-result.json"),result.ToString(Formatting.Indented)+Environment.NewLine);var after=SourceRuntimeManifest.Write(directory,"after-smoke-data",(string)runtime["path"]);SourceRuntimeManifest.RequireUnchanged(before,after);Console.WriteLine("[SourceSmokeData] result=Completed stages="+stages.Count+" world_allocated=False");
 }
}
